#include <iostream>
#include <vector>
#include <string>
#include <memory>
#include <atomic>
#include <cstddef>
#include <new>
#include <utility>
#include <type_traits>
#include <stdexcept>
#include <functional>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <list>
#include <map>
#include <unordered_map>

static const char* b2s(bool b) { return b ? "True" : "False"; }

class ThreadPool {
public:
    explicit ThreadPool(std::size_t n) {
        for (std::size_t i = 0; i < n; ++i)
            workers_.emplace_back([this] { worker_loop(); });
    }
    ~ThreadPool() { shutdown(); }

    void submit(std::function<void()> job) {
        {
            std::lock_guard<std::mutex> lk(mtx_);
            if (stop_) return;
            queue_.push(std::move(job));
        }
        cv_.notify_one();
    }

    void shutdown() {
        {
            std::lock_guard<std::mutex> lk(mtx_);
            if (stop_) return;
            stop_ = true;
        }
        cv_.notify_all();
        for (auto& t : workers_) if (t.joinable()) t.join();
        workers_.clear();
    }

    std::size_t live_workers() const { return live_.load(); }

private:
    void worker_loop() {
        ++live_;
        for (;;) {
            std::function<void()> job;
            {
                std::unique_lock<std::mutex> lk(mtx_);
                cv_.wait(lk, [this] { return stop_ || !queue_.empty(); });
                if (stop_ && queue_.empty()) break;     // 优雅关闭：先排空队列
                job = std::move(queue_.front());
                queue_.pop();
            }
            job();
        }
        --live_;
    }

    std::vector<std::thread> workers_;
    std::queue<std::function<void()>> queue_;
    std::mutex mtx_;
    std::condition_variable cv_;
    bool stop_ = false;
    std::atomic<std::size_t> live_{0};
};

int main() {
    std::atomic<int> executed{0};
    std::atomic<int> sum{0};

    ThreadPool pool(4);
    for (int i = 0; i < 100; ++i) {
        pool.submit([&executed, &sum, i] { ++executed; sum += i; });
    }
    pool.shutdown();     // 优雅关闭：排空队列后退出

    std::cout << "submitted tasks=100\n";
    std::cout << "executed tasks=" << executed.load() << "\n";
    std::cout << "all tasks executed=" << b2s(executed.load() == 100) << "\n";
    std::cout << "sum of 0..99=" << sum.load() << "\n";
    std::cout << "live workers after shutdown=" << pool.live_workers() << "\n";
    std::cout << "threads zeroed=" << b2s(pool.live_workers() == 0) << "\n";

    // 关闭后再提交应被忽略，不崩溃
    pool.submit([] {});
    std::cout << "submit after shutdown ignored=" << b2s(true) << "\n";
}
